import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import {
  Sesion,
  SesionDetalle,
  PaginatedSesiones,
} from '../models/sesion.model';
import { VistoBueno, VistoBuenoDecision } from '../models/visto-bueno.model';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class SesionService {
  private readonly http = inject(HttpClient);

  crearSesion(
    comiteId: number,
    payload: { fecha: string; hora: string; observaciones?: string }
  ): Observable<Sesion> {
    return this.http
      .post<{ data: Sesion }>(`${environment.apiUrl}/comites/${comiteId}/sesiones`, payload)
      .pipe(
        map(response => response.data),
      );
  }

  getSesiones(): Observable<PaginatedSesiones> {
    return this.http
      .get<{
        data: Sesion[];
        meta: {
          current_page: number;
          last_page: number;
          per_page: number;
          total: number;
          from: number;
          to: number;
        };
      }>(`${environment.apiUrl}/sesiones`)
      .pipe(
        map(response => ({
          ...response.meta,
          data: response.data,
        })),
      );
  }

  getMisPendientes(): Observable<Sesion[]> {
    return this.http
      .get<{ data: Sesion[] }>(`${environment.apiUrl}/sesiones/mis-pendientes`)
      .pipe(
        map(response => response.data),
      );
  }

  getSesion(id: number): Observable<SesionDetalle> {
    return this.http
      .get<{ data: SesionDetalle }>(`${environment.apiUrl}/sesiones/${id}`)
      .pipe(
        map(response => response.data),
      );
  }

  emitirVistoBueno(
    sesionId: number,
    payload: { decision: VistoBuenoDecision; observaciones?: string; evidenciaDocumentoId?: number }
  ): Observable<VistoBueno> {
    const body: Record<string, unknown> = { decision: payload.decision };
    if (payload.observaciones) {
      body['observaciones'] = payload.observaciones;
    }
    if (payload.evidenciaDocumentoId) {
      body['evidencia_documento_id'] = payload.evidenciaDocumentoId;
    }

    return this.http
      .post<{ data: VistoBueno }>(`${environment.apiUrl}/sesiones/${sesionId}/vistos-buenos`, body)
      .pipe(
        map(response => response.data),
      );
  }

  getVistosBuenos(sesionId: number): Observable<VistoBueno[]> {
    return this.http
      .get<{ data: VistoBueno[] }>(`${environment.apiUrl}/sesiones/${sesionId}/vistos-buenos`)
      .pipe(
        map(response => response.data),
      );
  }

  cerrarSesion(sesionId: number): Observable<Sesion> {
    return this.http
      .put<{ data: Sesion }>(`${environment.apiUrl}/sesiones/${sesionId}/cerrar`, {})
      .pipe(
        map(response => response.data),
      );
  }


}
